        int n = in.nextInt();
        int k = in.nextInt();
        HashSet<Integer> set = new HashSet<>();
        for (int i = 0; i < n; i++) {
            set.add(in.nextInt());
        }
        if(set.size() >= k){
            System.out.println(k);
        }else{
            System.out.println(set.size());
        }
    }
}
